descriptor.templateCss:
/* ==========================================================
   TABLA JSON POR DISPOSITIVO - estilo nativo de ThingsBoard
   Hereda color de texto, fondo, fuente y color primario del tema.
   Todo se puede sobrescribir desde los ajustes del widget.
   ========================================================== */

.attr-table {
    /* ---------- VARIABLES (valores nativos por defecto) ---------- */
    --at-primary: var(--tb-primary-color, var(--mdc-theme-primary, var(--mat-sys-primary, #305680)));
    --at-header-text: color-mix(in srgb, currentColor 62%, transparent);   /* ~ rgba(0,0,0,.54) */
    --at-row-text: currentColor;                                           /* ~ rgba(0,0,0,.87) */
    --at-header-bg: transparent;
    --at-row-bg: transparent;
    --at-hover-bg: color-mix(in srgb, currentColor 5%, transparent);       /* ~ rgba(0,0,0,.04) */
    --at-divider: color-mix(in srgb, currentColor 14%, transparent);       /* ~ rgba(0,0,0,.12) */
    --at-muted: color-mix(in srgb, currentColor 50%, transparent);

    width: 100%;
    height: 100%;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    color: inherit;
    background: transparent;
    font-family: inherit;
    font-size: 14px;
}

/* ---------- BARRA SUPERIOR (título, como en las tablas nativas) ---------- */
.attr-table__toolbar {
    display: flex;
    align-items: center;
    min-height: 48px;
    padding: 0 16px;
}

.attr-table__title {
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
    color: var(--at-title-color, inherit);
    font-family: var(--at-title-family, inherit);
    font-size: var(--at-title-size, 16px);
    font-weight: var(--at-title-weight, 400);
    font-style: var(--at-title-style, normal);
}

/* ---------- PIE: guardar / descartar + paginación ---------- */
.attr-table__footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 8px 16px;
    min-height: 48px;
    padding: 6px 16px;
}

.attr-table__actions {
    display: flex;
    gap: 8px;
}

.attr-table__paginator {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-left: auto;
    color: var(--at-header-text);
    font-size: 12px;
}

.attr-table__pager-select {
    width: 72px;
    height: 28px;
    font-size: 12px;
}

.attr-table__pager-range {
    min-width: 80px;
    text-align: center;
    white-space: nowrap;
}

.attr-table__btn {
    min-width: 64px;
    height: 36px;
    padding: 0 16px;
    border: 1px solid transparent;
    border-radius: 4px;
    font-family: inherit;
    font-size: 14px;
    font-weight: 500;
    letter-spacing: 0.0892857143em;
    cursor: pointer;
    transition: box-shadow 0.2s ease, background 0.2s ease;
}

.attr-table__btn--raised {
    background: var(--at-primary);
    color: var(--at-on-primary, #ffffff);
    box-shadow: 0 3px 1px -2px rgba(0, 0, 0, 0.2), 0 2px 2px 0 rgba(0, 0, 0, 0.14), 0 1px 5px 0 rgba(0, 0, 0, 0.12);
}

.attr-table__btn--raised:hover:not(:disabled) {
    box-shadow: 0 2px 4px -1px rgba(0, 0, 0, 0.2), 0 4px 5px 0 rgba(0, 0, 0, 0.14), 0 1px 10px 0 rgba(0, 0, 0, 0.12);
}

.attr-table__btn--outlined {
    background: transparent;
    color: var(--at-primary);
    border-color: color-mix(in srgb, currentColor 30%, transparent);
}

.attr-table__btn--outlined:hover:not(:disabled) {
    background: color-mix(in srgb, var(--at-primary) 8%, transparent);
}

.attr-table__btn:disabled {
    background: color-mix(in srgb, currentColor 12%, transparent);
    color: color-mix(in srgb, currentColor 38%, transparent);
    border-color: transparent;
    box-shadow: none;
    cursor: default;
}

/* ---------- TABLA ---------- */
.attr-table__scroll {
    flex: 1;
    min-height: 0;
    overflow: auto;
}

.attr-table__table {
    width: 100%;
    border-collapse: collapse;
}

.attr-table__table th {
    height: 40px;
    padding: 0 16px;
    text-align: left;
    white-space: nowrap;
    background: var(--at-header-bg);
    color: var(--at-header-text);
    border-bottom: 1px solid var(--at-divider);
    font-family: var(--at-header-family, inherit);
    font-size: var(--at-header-size, 12px);
    font-weight: var(--at-header-weight, 500);
    font-style: var(--at-header-style, normal);
}

.attr-table__table td {
    height: 48px;
    padding: 0 16px;
    text-align: left;
    white-space: nowrap;
    color: var(--at-row-text);
    border-bottom: 1px solid var(--at-divider);
    font-family: var(--at-row-family, inherit);
    font-size: var(--at-row-size, 14px);
    font-weight: var(--at-row-weight, 400);
    font-style: var(--at-row-style, normal);
}

.attr-table__row {
    background: var(--at-row-bg);
    transition: background 0.15s ease;
}

.attr-table__row:hover {
    background: var(--at-hover-bg);
}

.attr-table__row--saving {
    opacity: 0.6;
}

.attr-table__row--dirty td:first-child {
    box-shadow: inset 3px 0 0 var(--at-primary);
}

.attr-table__missing,
.attr-table__value--empty {
    color: var(--at-muted);
}

.attr-table__unit {
    margin-left: 2px;
    font-size: 12px;
    color: var(--at-muted);
}

.attr-table__empty {
    padding: 16px;
    color: var(--at-muted);
}

/* ---------- CASILLA (estilo Material) ---------- */
.attr-table__checkbox {
    -webkit-appearance: none;
    appearance: none;
    position: relative;
    width: 18px;
    height: 18px;
    margin: 0;
    border: 2px solid color-mix(in srgb, currentColor 54%, transparent);
    border-radius: 2px;
    background: transparent;
    cursor: pointer;
    vertical-align: middle;
    transition: background 0.15s ease, border-color 0.15s ease;
}

.attr-table__checkbox:checked {
    background: var(--at-primary);
    border-color: var(--at-primary);
}

.attr-table__checkbox:checked::after {
    content: '';
    position: absolute;
    left: 3px;
    top: -1px;
    width: 5px;
    height: 10px;
    border: solid var(--at-on-primary, #ffffff);
    border-width: 0 2px 2px 0;
    transform: rotate(45deg);
}

/* ---------- BOTONES DE TEXTO E ÍCONOS ---------- */
.attr-table__link-btn {
    height: 28px;
    padding: 0 8px;
    border: none;
    border-radius: 4px;
    background: transparent;
    color: var(--at-primary);
    font-family: inherit;
    font-size: 12px;
    font-weight: 500;
    cursor: pointer;
}

.attr-table__link-btn:hover {
    background: color-mix(in srgb, var(--at-primary) 8%, transparent);
}

.attr-table__icon-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    padding: 0;
    margin-left: 4px;
    border: none;
    border-radius: 50%;
    background: transparent;
    color: var(--at-header-text);
    cursor: pointer;
    vertical-align: middle;
}

.attr-table__icon-btn:hover:not(:disabled) {
    background: var(--at-hover-bg);
    color: var(--at-primary);
}

.attr-table__icon-btn:disabled {
    opacity: 0.38;
    cursor: default;
}

.attr-table__icon {
    width: 18px;
    height: 18px;
    font-size: 18px;
    line-height: 18px;
}

/* ---------- EDICIÓN (texto, número, opciones) ---------- */
.attr-table__editor {
    display: inline-flex;
    align-items: center;
}

.attr-table__input,
.attr-table__select {
    max-width: 160px;
    height: 32px;
    padding: 0 8px;
    box-sizing: border-box;
    border: 1px solid color-mix(in srgb, currentColor 38%, transparent);
    border-radius: 4px;
    background: transparent;
    color: inherit;
    font-family: inherit;
    font-size: inherit;
}

.attr-table__input:focus,
.attr-table__select:focus {
    outline: none;
    border-color: var(--at-primary);
    box-shadow: 0 0 0 1px var(--at-primary);
}

.attr-table__select option {
    background: Canvas;
    color: CanvasText;
}

/* ---------- MENSAJE DE RESPALDO (si no hay notificaciones nativas) ---------- */
.attr-table__fallback {
    padding: 8px 16px;
    font-size: 12px;
    color: var(--at-muted);
}

/* ==========================================================
   TEMAS SMELPRO (mismos que el Fuel Gauge)
   - Industrial: oscuro, acento amarillo  (por defecto)
   - Ejecutivo : claro, acento ámbar
   Los colores configurados en los ajustes del widget tienen prioridad.
   ========================================================== */
:host { display: block; width: 100%; height: 100%; min-width: 0; min-height: 0; overflow: hidden; }

.attr-table,
.attr-table.at-industrial {
    --at-text: #edf3f8;
    --at-primary: #f2c300;
    --at-on-primary: #101820;
    --at-header-text: #91a2b3;
    --at-row-text: #edf3f8;
    --at-header-bg: rgba(255, 255, 255, .035);
    --at-row-bg: transparent;
    --at-hover-bg: color-mix(in srgb, var(--at-primary) 9%, transparent);
    --at-divider: rgba(255, 255, 255, .08);
    --at-muted: #91a2b3;
    --at-surface: rgba(255, 255, 255, .04);
    --at-panel: rgba(0, 0, 0, .18);
    --at-border: #293846;
    --at-border-strong: #3a4d5e;
    --at-input-bg: #101820;
    --at-root-bg: radial-gradient(ellipse at 50% 100%, rgba(242, 195, 0, .07), transparent 62%), linear-gradient(145deg, #17232e, #101820);
}

.attr-table.at-light {
    --at-text: #263445;
    --at-primary: #d99a00;
    --at-on-primary: #1f2d3d;
    --at-header-text: #778596;
    --at-row-text: #263445;
    --at-header-bg: rgba(38, 52, 69, .04);
    --at-row-bg: transparent;
    --at-hover-bg: color-mix(in srgb, var(--at-primary) 10%, transparent);
    --at-divider: #e4e9ef;
    --at-muted: #778596;
    --at-surface: #ffffff;
    --at-panel: #ffffff;
    --at-border: #e4e9ef;
    --at-border-strong: #c5ced8;
    --at-input-bg: #ffffff;
    --at-root-bg: linear-gradient(145deg, #ffffff, #f4f7fa);
}

.attr-table { position: relative; color: var(--at-text); background: var(--at-root-bg); padding: 14px; gap: 10px; border-radius: 18px; }

/* ---------- Barra del título (con icono) ---------- */
.attr-table__toolbar { flex: 0 0 auto; gap: 12px; justify-content: space-between; background: transparent; border: 0; border-radius: 0; min-height: 40px; padding: 0 2px; }
.attr-table__heading { display: flex; align-items: center; gap: 10px; min-width: 0; }
.attr-table__title { color: var(--at-title-color, var(--at-text)); font-weight: var(--at-title-weight, 700); letter-spacing: .2px; }
.attr-table__title-icon {
    --at-ico: var(--at-title-icon-size, 18px);
    display: inline-flex; align-items: center; justify-content: center; flex: 0 0 auto; box-sizing: content-box;
    width: var(--at-ico); height: var(--at-ico); padding: 7px; border-radius: 9px;
    font-size: var(--at-ico); line-height: 1; color: var(--at-primary);
    border: 1px solid color-mix(in srgb, var(--at-primary) 70%, transparent);
    background: color-mix(in srgb, var(--at-primary) 12%, var(--at-input-bg));
}
.attr-table__title-icon .mat-icon, .attr-table__title-icon mat-icon, .attr-table__title-icon svg {
    width: var(--at-ico); height: var(--at-ico); font-size: var(--at-ico); line-height: var(--at-ico); color: inherit; fill: currentColor;
}

/* ---------- Tabla ---------- */
.attr-table__scroll { border: 1px solid var(--at-border); border-radius: 14px; background: var(--at-panel); scrollbar-color: var(--at-border-strong) transparent; }
.attr-table__table th { height: 44px; font-weight: var(--at-header-weight, 600); letter-spacing: .2px; }
.attr-table__table td { height: 50px; }
.attr-table__row:last-child td { border-bottom-color: transparent; }

/* ---------- Pie y botones ---------- */
.attr-table__footer { position: relative; flex: 0 0 auto; border: 1px solid var(--at-border); border-radius: 12px; background: var(--at-surface); }
.attr-table__btn { border-radius: 10px; text-transform: none; letter-spacing: 0; }
.attr-table__btn--raised { background: linear-gradient(90deg, var(--at-primary), color-mix(in srgb, var(--at-primary) 78%, #000)); color: var(--at-on-primary); border-color: transparent; }
.attr-table__btn--outlined { color: var(--at-text); border-color: var(--at-border-strong); }
.attr-table__btn--outlined:hover:not(:disabled) { background: var(--at-hover-bg); }

/* ---------- Controles ---------- */
.attr-table__input, .attr-table__select { border-radius: 9px; border-color: var(--at-border-strong); background: var(--at-input-bg); color: var(--at-text); }
.attr-table__select option { background: var(--at-input-bg); color: var(--at-text); }
.attr-table__link-btn { color: var(--at-primary); }
.attr-table__icon-btn { color: var(--at-header-text); }
.attr-table__icon-btn:hover:not(:disabled) { background: var(--at-hover-bg); color: var(--at-primary); }
.attr-table__checkbox { border-color: var(--at-muted); border-radius: 4px; }
.attr-table__checkbox:checked { border-color: var(--at-primary); }
.attr-table__paginator { color: var(--at-header-text); }

/* ---------- Campos detectados (ayuda contextual) ---------- */
.attr-table__detected-toggle { margin-left: 0; height: 36px; border: 1px solid var(--at-primary); background: color-mix(in srgb, var(--at-primary) 10%, transparent); color: var(--at-text); border-radius: 9px; padding: 7px 10px; cursor: pointer; white-space: nowrap; font-size: 12px; font-family: inherit; }
.attr-table__detected-toggle:hover { background: color-mix(in srgb, var(--at-primary) 24%, transparent); }
.attr-table__detected-keys { position: absolute; left: 0; right: 0; bottom: calc(100% + 6px); z-index: 6; display: flex; gap: 6px; flex-wrap: wrap; padding: 10px 15px; border: 1px solid var(--at-border-strong); border-radius: 12px; background: var(--at-input-bg); box-shadow: 0 8px 24px rgba(0,0,0,.35); color: var(--at-header-text); font-size: 12px; max-height: 106px; overflow-y: auto; }
.attr-table__detected-chip { border: 1px solid var(--at-border-strong); background: var(--at-input-bg); border-radius: 8px; color: var(--at-text); padding: 5px 9px; cursor: pointer; font-family: inherit; font-size: 12px; }
.attr-table__detected-chip:hover { border-color: var(--at-primary); background: color-mix(in srgb, var(--at-primary) 18%, var(--at-input-bg)); }

/* ---------- Diagnóstico de orígenes ---------- */
.attr-table__diag-toggle { gap: 8px; align-items: center; }
.attr-table__tools { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.attr-table__diag-dot { width: 9px; height: 9px; border-radius: 50%; background: var(--at-muted); flex: 0 0 auto; }
.attr-table__diag-dot--ok { background: #42c88b; }
.attr-table__diag-dot--warn { background: #f2a516; }
.attr-table__diag-dot--error { background: #ff5a52; }
.attr-table__diag { position: absolute; left: 0; right: 0; bottom: calc(100% + 6px); z-index: 6; flex-direction: column; gap: 6px; padding: 10px 14px; border: 1px solid var(--at-border-strong); border-radius: 12px; background: var(--at-input-bg); box-shadow: 0 8px 24px rgba(0,0,0,.35); font-size: 12px; max-height: 180px; overflow-y: auto; }
.attr-table__diag-item { display: flex; align-items: flex-start; gap: 8px; line-height: 18px; color: var(--at-text); }
.attr-table__diag-item .attr-table__icon { flex: 0 0 auto; width: 18px; height: 18px; font-size: 18px; }
.attr-table__diag-item--ok .attr-table__icon { color: #42c88b; }
.attr-table__diag-item--warn .attr-table__icon { color: #f2a516; }
.attr-table__diag-item--error .attr-table__icon { color: #ff5a52; }

descriptor.controllerScript:
self.onInit = function() {

    // ======================================================
    // 1. REFERENCIAS Y CONFIGURACIÓN
    // ======================================================
    var ctx = self.ctx;
    var settings = ctx.settings || {};
    var root = ctx.$container[0];
    if (!root) { return; }

    var widgetEl = root.querySelector('.attr-table');
    var toolbarEl = root.querySelector('.attr-table__toolbar');
    var titleEl = root.querySelector('.attr-table__title');
    var footerEl = root.querySelector('.attr-table__footer');
    var actionsEl = root.querySelector('.attr-table__actions');
    var paginatorEl = root.querySelector('.attr-table__paginator');
    var scrollEl = root.querySelector('.attr-table__scroll');
    var fallbackEl = root.querySelector('.attr-table__fallback');
    var saveBtn = root.querySelector('[data-action="save"]');
    var discardBtn = root.querySelector('[data-action="discard"]');

    function clean(value) {
        return (value || '').toString().trim();
    }

    var SINGLE_KEY = '__single__';       // columna para atributos que son un valor simple
    var CUSTOM_OPTION = '__custom__';    // opción "Otro..." de las listas

    var attributeScope = clean(settings.attributeScope) || 'SERVER_SCOPE';   // ámbito donde se GUARDA
    var autoSave = settings.autoSave === true;   // por defecto: guardado manual (Descartar / Guardar cambios)
    var showRowButtons = settings.showRowButtons !== false;

    // Paginación: dispositivos por página (el usuario puede cambiarlo desde el pie de la tabla)
    var paginationEnabled = settings.enablePagination !== false;
    var pageSize = Math.floor(Number(settings.pageSize));
    if (!(pageSize > 0)) { pageSize = 10; }
    var pageIndex = 0;

    var defaultKeys = [];
    var customLabels = {};

    // Actualizaciones exclusivamente desde la suscripción del widget (WebSocket).

    // ---- Campos declarados en los ajustes (vacío = detectar todos los campos del JSON) ----
    function toNumberOrNull(value) {
        if (value === undefined || value === null || value === '') { return null; }
        var number = Number(value);
        return isNaN(number) ? null : number;
    }

    // "auto,manual,eco"  o  "1=Bajo,2=Medio"  ->  [{ value, label }]
    function parseOptions(text, type) {
        var options = [];
        clean(text).split(',').forEach(function(part) {
            var piece = clean(part);
            if (!piece) { return; }
            var eq = piece.indexOf('=');
            var rawValue = clean(eq === -1 ? piece : piece.slice(0, eq));
            var label = clean(eq === -1 ? piece : piece.slice(eq + 1)) || rawValue;
            var value = rawValue;
            if (type === 'number') {
                value = Number(rawValue);
                if (isNaN(value)) { return; }
            }
            options.push({ value: value, label: label });
        });
        return options;
    }

    // Modo de entrada de cada campo:
    //   texto  -> 'free' (libre) | 'options' (valores predefinidos)
    //   número -> 'limits' (con mínimo / máximo) | 'options' (valores predefinidos)
    function resolveMode(field, type) {
        var hasOptionsText = !!clean(field.options);
        var chosen = clean(type === 'string' ? field.stringMode : field.numberMode);
        var wantsOptions = chosen === 'options' || (!chosen && hasOptionsText);   // compatibilidad con la versión anterior
        if (wantsOptions) { return 'options'; }
        return type === 'string' ? 'free' : 'limits';
    }

    var declaredFields = (Array.isArray(settings.fields) ? settings.fields : [])
        .filter(function(field) { return field && clean(field.key); })
        .map(function(field) {
            var type = (['boolean', 'string', 'number'].indexOf(field.type) !== -1) ? field.type : 'boolean';
            var restrictions = field.enableRestrictions === true;
            var mode = type === 'boolean' ? 'boolean' : (restrictions ? resolveMode(field, type) : (type === 'string' ? 'free' : 'limits'));
            var options = mode === 'options' ? parseOptions(field.options, type) : [];
            if (mode === 'options' && !options.length) { mode = (type === 'string') ? 'free' : 'limits'; }
            return {
                key: clean(field.key),
                label: clean(field.label),
                type: type,
                mode: mode,
                options: options,
                allowCustom: restrictions && mode === 'options' && !!field.allowCustom,
                min: restrictions && type === 'number' ? toNumberOrNull(field.min) : null,
                max: restrictions && type === 'number' ? toNumberOrNull(field.max) : null,
                unit: type === 'number' ? clean(field.unit) : '',
                required: restrictions && !!field.requiredValue,
                readOnly: !!field.readOnly,
                integer: restrictions && !!field.integer,
                step: restrictions ? toNumberOrNull(field.step) : null,
                minLength: restrictions ? toNumberOrNull(field.minLength) : null,
                maxLength: restrictions ? toNumberOrNull(field.maxLength) : null,
                pattern: restrictions ? clean(field.pattern) : '',
                trim: restrictions && !!field.trimText
            };
        });

    // Estado general
    var devices = {};          // id -> dispositivo
    var valuesById = {};       // id -> { claveDeDatos: texto } (columnas iniciales)
    var order = [];            // ids ordenados por nombre
    var editing = null;        // { id, key, kind, draft } celda en edición
    var emptyText = 'Configura dos orígenes: 1) Nombre del dispositivo (campo entidad name), 2) Atributo JSON (tipo atributo).';
    var initialized = false;   // ya llegó al menos una respuesta

    // Cada dispositivo: { id, entityType, name, exists, model:{mode,data}, remoteModel,
    //                     dirty, pending, loading, version, lastSaveEnd }

    // ======================================================
    // 2. ESTILO (fuentes y colores configurables, con valores nativos por defecto)
    // ======================================================
    function applyFont(prefix, font) {
        if (!font || typeof font !== 'object') { return; }
        var style = widgetEl.style;
        if (font.size) { style.setProperty('--at-' + prefix + '-size', font.size + (font.sizeUnit || 'px')); }
        if (font.family) { style.setProperty('--at-' + prefix + '-family', font.family); }
        if (font.weight) { style.setProperty('--at-' + prefix + '-weight', font.weight); }
        if (font.style) { style.setProperty('--at-' + prefix + '-style', font.style); }
    }

    function applyColor(settingKey, cssVariable) {
        var value = clean(settings[settingKey]);
        if (value) { widgetEl.style.setProperty(cssVariable, value); }
    }

    applyFont('header', settings.headerFont);
    applyFont('row', settings.rowFont);
    applyColor('headerTextColor', '--at-header-text');
    applyColor('headerBackgroundColor', '--at-header-bg');
    applyColor('rowTextColor', '--at-row-text');
    applyColor('rowBackgroundColor', '--at-row-bg');
    applyColor('rowHoverColor', '--at-hover-bg');
    applyColor('dividerColor', '--at-divider');
    applyColor('accentColor', '--at-primary');
    // Texto legible sobre el color tema (botones y marca de las casillas)
    (function() {
        var c = clean(settings.accentColor), m, r, g, b;
        if (!c) { return; }
        if ((m = /^#([0-9a-f]{3}|[0-9a-f]{6})([0-9a-f]{2})?$/i.exec(c))) {
            var x = m[1].length === 3 ? m[1].replace(/(.)/g, '$1$1') : m[1];
            r = parseInt(x.slice(0, 2), 16); g = parseInt(x.slice(2, 4), 16); b = parseInt(x.slice(4, 6), 16);
        } else if ((m = /^rgba?\(\s*(\d+)[,\s]+(\d+)[,\s]+(\d+)/i.exec(c))) {
            r = +m[1]; g = +m[2]; b = +m[3];
        } else { return; }
        var lum = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
        widgetEl.style.setProperty('--at-on-primary', lum > 0.6 ? '#101820' : '#ffffff');
    })();
    applyFont('title', settings.titleFont);
    applyColor('titleColor', '--at-title-color');

    // ---- Tema visual (Industrial oscuro / Ejecutivo claro) ----
    var themeName = settings.theme === 'executive' ? 'executive' : 'industrial';
    widgetEl.classList.add(themeName === 'executive' ? 'at-light' : 'at-industrial');

    // ---- Icono del título (Material, mdi: o svg: de ThingsBoard) ----
    var titleIconName = clean(settings.titleIcon);
    var showTitleIcon = settings.showTitleIcon === true && !!titleIconName;
    if (showTitleIcon) {
        var iconSize = Math.floor(Number(settings.titleIconSize));
        if (!(iconSize >= 12 && iconSize <= 32)) { iconSize = 18; }
        widgetEl.style.setProperty('--at-title-icon-size', iconSize + 'px');
    }
    if (ctx.$scope) {
        ctx.$scope.vm = { titleIcon: showTitleIcon ? titleIconName : '' };
        if (typeof ctx.detectChanges === 'function') { ctx.detectChanges(); }
    }

    var detectedKeysEl = document.createElement('div');
    detectedKeysEl.className = 'attr-table__detected-keys';
    detectedKeysEl.style.display = 'none';
    var detectedKeysShown = false;
    var detectedToggle = document.createElement('button');
    detectedToggle.type = 'button';
    detectedToggle.className = 'attr-table__detected-toggle';
    detectedToggle.textContent = 'Ver campos JSON';
    detectedToggle.title = 'Consulta los nombres reales detectados en los atributos JSON';
    detectedToggle.style.display = settings.showDetectedFields === false ? 'none' : 'inline-flex';
    detectedToggle.addEventListener('click', function() {
        detectedKeysShown = !detectedKeysShown;
        renderDetectedKeys();
    });
    var diagShown = false;
    var diagToggle = document.createElement('button');
    diagToggle.type = 'button';
    diagToggle.className = 'attr-table__detected-toggle attr-table__diag-toggle';
    diagToggle.title = 'Verifica que la columna de datos y el atributo JSON estén bien configurados';
    diagToggle.style.display = settings.showDiagnostics === false ? 'none' : 'inline-flex';
    var diagDot = document.createElement('span');
    diagDot.className = 'attr-table__diag-dot';
    var diagLabel = document.createElement('span');
    diagLabel.textContent = 'Diagnóstico';
    diagToggle.appendChild(diagDot);
    diagToggle.appendChild(diagLabel);
    diagToggle.addEventListener('click', function() { diagShown = !diagShown; renderDiagnostics(); });
    var diagPanel = document.createElement('div');
    diagPanel.className = 'attr-table__diag';
    diagPanel.style.display = 'none';
    // Botones de ayuda en el pie, junto a Descartar / Guardar cambios; los paneles se abren sobre el pie.
    var toolsEl = document.createElement('div');
    toolsEl.className = 'attr-table__tools';
    toolsEl.appendChild(diagToggle);
    toolsEl.appendChild(detectedToggle);
    var toolsVisible = settings.showDiagnostics !== false || settings.showDetectedFields !== false;
    toolsEl.style.display = toolsVisible ? 'flex' : 'none';
    footerEl.insertBefore(toolsEl, footerEl.firstChild);
    footerEl.appendChild(diagPanel);
    footerEl.appendChild(detectedKeysEl);
    function renderDetectedKeys() {
        detectedKeysEl.replaceChildren();
        detectedKeysEl.style.display = detectedKeysShown ? 'flex' : 'none';
        detectedToggle.textContent = detectedKeysShown ? 'Ocultar campos JSON' : 'Ver campos JSON';
        if (!detectedKeysShown) return;
        var found = {};
        order.forEach(function(id) {
            var model = devices[id].model;
            if (model.mode !== 'object' || !model.data) return;
            Object.keys(model.data).forEach(function(key) { found[key] = true; });
        });
        var names = Object.keys(found).sort();
        if (!names.length) {
            var empty = document.createElement('span');
            empty.textContent = 'No se detectaron campos todavía.';
            detectedKeysEl.appendChild(empty); return;
        }
        names.forEach(function(key) {
            var chip = document.createElement('button');
            chip.type = 'button';
            chip.className = 'attr-table__detected-chip';
            chip.textContent = key;
            chip.title = 'Copiar nombre del campo: ' + key;
            chip.addEventListener('click', function() {
                if (navigator.clipboard && navigator.clipboard.writeText) {
                    navigator.clipboard.writeText(key).then(function() { notify('success', 'Campo copiado: ' + key); })
                        .catch(function() { notify('error', 'No se pudo copiar el campo.'); });
                } else { notify('error', 'Selecciona y copia manualmente el nombre: ' + key); }
            });
            detectedKeysEl.appendChild(chip);
        });
    }

    var titleText = clean(settings.title);
    if (titleText) {
        titleEl.textContent = titleText;
        titleEl.title = titleText;
        toolbarEl.style.display = 'flex';
    }
    toolbarEl.style.display = 'flex';

    // ======================================================
    // 3. NOTIFICACIONES Y DIÁLOGOS NATIVOS
    // ======================================================
    // Avisos con el sistema de notificaciones de ThingsBoard.
    function notify(type, message) {
        var target = ctx.toastTargetId;
        try {
            if (type === 'success' && typeof ctx.showSuccessToast === 'function') {
                ctx.showSuccessToast(message, 2000, 'bottom', 'left', target);
                return;
            }
            if (type === 'error' && typeof ctx.showErrorToast === 'function') {
                ctx.showErrorToast(message, 'bottom', 'left', target);
                return;
            }
            if (typeof ctx.showToast === 'function') {
                ctx.showToast(type, message, 2000, 'bottom', 'left', target);
                return;
            }
        } catch (e) { /* se usa el respaldo */ }

        fallbackEl.textContent = message;
        fallbackEl.style.display = 'block';
        setTimeout(function() { fallbackEl.style.display = 'none'; }, 3000);
    }

    // Ventana de confirmación nativa de ThingsBoard (con respaldo del navegador).
    function confirmAction(title, message, onConfirm, onCancel) {
        function decide(accepted) {
            if (accepted) { onConfirm(); }
            else if (onCancel) { onCancel(); }
        }
        try {
            if (ctx.dialogs && typeof ctx.dialogs.confirm === 'function') {
                ctx.dialogs.confirm(title, message, 'Cancelar', 'Confirmar').subscribe(decide);
                return;
            }
        } catch (e) { /* se usa el respaldo */ }
        decide(window.confirm(title + '\n\n' + message));
    }

    // ======================================================
    // 4. UTILIDADES
    // ======================================================
    function errorDetail(error) {
        var detail = error && (error.message || (error.error && error.error.message) || error.status);
        return detail ? ' (' + detail + ')' : '';
    }

    function prettify(key) {
        var text = key.replace(/([a-z])([A-Z])/g, '$1 $2').replace(/[_-]+/g, ' ').trim();
        return text.charAt(0).toUpperCase() + text.slice(1);
    }

    function cloneModel(model) {
        return JSON.parse(JSON.stringify(model));
    }

    // Tipo de un valor simple (o null si es objeto, lista o vacío).
    function valueKind(value) {
        if (typeof value === 'boolean') { return 'boolean'; }
        if (typeof value === 'number') { return 'number'; }
        if (typeof value === 'string') { return 'string'; }
        return null;
    }

    // Nombre en español del tipo de un valor, para los mensajes.
    function kindLabel(value) {
        if (value === null) { return 'vacío'; }
        if (Array.isArray(value)) { return 'lista'; }
        var kind = valueKind(value);
        if (kind === 'boolean') { return 'booleano'; }
        if (kind === 'number') { return 'número'; }
        if (kind === 'string') { return 'texto'; }
        return 'objeto';
    }

    // Convierte el valor guardado al tipo declarado para mostrarlo.
    function coerce(raw, type) {
        if (type === 'boolean') { return raw === true || raw === 'true' || raw === 1 || raw === '1'; }
        if (type === 'number') {
            if (typeof raw === 'number') { return raw; }
            return isNaN(Number(raw)) ? raw : Number(raw);
        }
        if (typeof raw === 'string') { return raw; }
        return (raw !== null && typeof raw === 'object') ? JSON.stringify(raw) : String(raw);
    }

    // Convierte el valor (objeto, valor simple o texto JSON) en el modelo interno.
    function parseValue(raw) {
        var value = raw;
        if (typeof value === 'string') {
            try { value = JSON.parse(value); } catch (e) { /* se queda como texto */ }
        }
        if (value !== null && typeof value === 'object') {
            return { mode: 'object', data: Array.isArray(value) ? {} : cloneModel(value) };
        }
        if (valueKind(value)) { return { mode: 'single', data: value }; }
        return { mode: 'object', data: {} };
    }

    function buildLoadedModel(exists, raw) {
        var loadedModel = parseValue(exists ? raw : null);
        // Sin campos declarados y sin atributo: se pueden proponer campos booleanos iniciales.
        if (!exists && !declaredFields.length && defaultKeys.length) {
            defaultKeys.forEach(function(key) { loadedModel.data[key] = false; });
        }
        return loadedModel;
    }

    // Lo que se guarda: el objeto original con los campos editados.
    // Los campos que no se tocaron se conservan tal cual.
    function buildPayload(device) {
        return cloneModel({ v: device.model.data }).v;
    }

    function anyDirty() {
        return order.some(function(id) { return devices[id].dirty; });
    }

    // Los botones Descartar / Guardar cambios solo existen con guardado manual.
    function updateActions() {
        actionsEl.style.display = autoSave ? 'none' : 'flex';
        footerEl.style.display = (!autoSave || paginationEnabled || toolsVisible) ? 'flex' : 'none';
        var dirty = anyDirty();
        saveBtn.disabled = !dirty;
        discardBtn.disabled = !dirty;
    }

    function setEmptyText(text) {
        emptyText = text;
        if (!order.length) { renderTable(); }
    }

    // ======================================================
    // 5. COLUMNAS Y CELDAS
    // ======================================================
    // Columnas = campos declarados o, si no hay, unión de los campos simples de todos los dispositivos.
    function getColumns() {
        if (declaredFields.length) {
            return declaredFields.map(function(field) {
                return { key: field.key, label: field.label || customLabels[field.key] || prettify(field.key), field: field };
            });
        }

        var columns = [];
        var seen = {};
        function add(key, label) {
            if (!seen[key]) {
                seen[key] = true;
                columns.push({ key: key, label: label, field: null });
            }
        }
        order.forEach(function(id) {
            var device = devices[id];
            if (device.model.mode === 'single') {
                add(SINGLE_KEY, customLabels[getAttributeName()] || prettify(getAttributeName()));
                return;
            }
            Object.keys(device.model.data).forEach(function(key) {
                if (valueKind(device.model.data[key])) { add(key, customLabels[key] || prettify(key)); }
            });
        });
        return columns;
    }

    // Información de una celda: { kind, value, missing } o null si no aplica (se muestra "–").
    function getCellInfo(device, column) {
        if (column.key === SINGLE_KEY) {
            if (device.model.mode !== 'single') { return null; }
            return { kind: valueKind(device.model.data), value: device.model.data, missing: false };
        }
        if (device.model.mode !== 'object') { return null; }

        var raw = device.model.data[column.key];
        if (column.field) {
            if (raw === undefined || raw === null) { return { kind: column.field.type, value: undefined, missing: true }; }
            return { kind: column.field.type, value: coerce(raw, column.field.type), missing: false };
        }
        var kind = valueKind(raw);
        return kind ? { kind: kind, value: raw, missing: false } : null;
    }

    function setCellValue(device, column, value) {
        if (column.key === SINGLE_KEY) { device.model.data = value; }
        else { device.model.data[column.key] = value; }
    }

    function isBooleanColumn(column) {
        if (column.field) { return column.field.type === 'boolean'; }
        return order.some(function(id) {
            var info = getCellInfo(devices[id], column);
            return info && info.kind === 'boolean';
        });
    }

    // ======================================================
    // 6. DISPOSITIVOS Y CLAVES DE DATOS
    // ======================================================
    function getDatasources() {
        var list = [];
        if (ctx.datasources) { list = list.concat(ctx.datasources); }
        var subscription = ctx.defaultSubscription;
        if (subscription) {
            if (subscription.datasources) { list = list.concat(subscription.datasources); }
            if (subscription.configuredDatasources) { list = list.concat(subscription.configuredDatasources); }
        }
        return list;
    }

    function sameKey(a, b) {
        return !!(a && b && a.name === b.name && a.type === b.type);
    }

    function keyId(key) {
        return key.type + '|' + key.name;
    }

    // DOS FUENTES EXPLICITAS:
    // fuente 1 (indice 0): nombre o etiqueta mostrada en primera columna.
    // fuente 2 (indice 1): atributo JSON que se edita.
    // Ambas deben apuntar al mismo alias/conjunto de entidades.
    function configuredSource(index) {
        var configured = ctx.defaultSubscription && ctx.defaultSubscription.configuredDatasources;
        if (configured && configured[index]) return configured[index];
        var live = ctx.datasources || [];
        if (live[index]) return live[index];
        var subs = ctx.defaultSubscription && ctx.defaultSubscription.datasources || [];
        return subs[index] || null;
    }

    // Cada clave se identifica por su FUNCIÓN (ajuste "Función de esta clave de datos"),
    // no solo por el orden del origen:
    //   deviceName    -> columna de datos (1.ª columna)
    //   jsonAttribute -> atributo JSON editable
    //   auto          -> 1.ª clave = columna de datos; la siguiente clave de tipo Atributo = JSON
    // Funciona con 2 orígenes (1 clave c/u) o con 1 origen que tenga las 2 claves.
    function keyRole(key) {
        var role = clean(key && key.settings && key.settings.smelproKeyRole);
        return (role === 'deviceName' || role === 'jsonAttribute') ? role : 'auto';
    }

    function resolveKeys() {
        var flat = [];
        for (var i = 0; i < 6; i++) {
            var source = configuredSource(i);
            if (!source) { break; }
            (Array.isArray(source.dataKeys) ? source.dataKeys : []).forEach(function(key) {
                if (key) { flat.push({ key: key, ds: i, role: keyRole(key) }); }
            });
        }
        var json = flat.filter(function(r) { return r.role === 'jsonAttribute'; })[0] || null;
        var data = flat.filter(function(r) { return r.role === 'deviceName'; })[0] || null;
        if (!data) { data = flat.filter(function(r) { return r !== json && r.role === 'auto'; })[0] || null; }
        var badType = null;
        if (json && json.key.type !== 'attribute') { badType = json; json = null; }
        if (!json && !badType) {
            json = flat.filter(function(r) { return r !== data && r.role === 'auto' && r.key.type === 'attribute'; })[0] || null;
            if (!json) { badType = flat.filter(function(r) { return r !== data && r.role === 'auto'; })[0] || null; }
        }
        return { data: data ? data.key : null, json: json ? json.key : null, badType: badType ? badType.key : null, flat: flat };
    }

    function getNameKey() { return resolveKeys().data; }
    function getControlKey() { return resolveKeys().json; }
    function getInfoKeys() { return getNameKey() ? [getNameKey()] : []; }
    function getKeyLabel(key) {
        if (!key) return 'Dispositivo';
        return clean(key.label) || clean(key.settings && key.settings.label) || clean(key.name) || 'Dispositivo';
    }
    function getAttributeName() {
        var key = getControlKey();
        return key ? key.name : '';
    }

    function formatValue(value) {
        if (value === null || value === undefined) { return ''; }
        if (typeof value === 'object') { return JSON.stringify(value); }
        return String(value);
    }

    // Extrae id, tipo y nombre de un datasource (una entidad resuelta del alias).
    function getDeviceInfo(ds) {
        if (!ds || !ds.entityId) { return null; }
        var id = (typeof ds.entityId === 'object') ? ds.entityId.id : ds.entityId;
        var entityType = ds.entityType || (typeof ds.entityId === 'object' ? ds.entityId.entityType : null);
        if (!id || !entityType) { return null; }
        var name = clean(ds.entityLabel) || clean(ds.entityName) || clean(ds.name) || id;
        return { id: id, entityType: entityType, name: name };
    }

    // Actualiza los textos de las columnas iniciales. Devuelve true si algo cambió.
    function updateInfoValues() {
        var infoKeys = getInfoKeys();
        if (!infoKeys.length || !ctx.data) { return false; }

        var changed = false;
        ctx.data.forEach(function(entry) {
            if (!entry || !entry.dataKey || !entry.datasource) { return; }
            var isInfo = infoKeys.some(function(key) { return sameKey(key, entry.dataKey); });
            if (!isInfo) { return; }
            var info = getDeviceInfo(entry.datasource);
            if (!info) { return; }

            var series = entry.data;
            var text = formatValue((series && series.length) ? series[series.length - 1][1] : undefined);
            var bucket = valuesById[info.id] || (valuesById[info.id] = {});
            if (bucket[keyId(entry.dataKey)] !== text) {
                bucket[keyId(entry.dataKey)] = text;
                changed = true;
            }
        });
        return changed;
    }

    // Texto que identifica al dispositivo: primera clave inicial o, si no hay, su nombre.
    function getDisplayName(device) {
        var infoKeys = getInfoKeys();
        if (infoKeys.length) {
            var text = (valuesById[device.id] || {})[keyId(infoKeys[0])];
            if (text) { return text; }
        }
        return device.name;
    }

    // Dispositivos que resuelve el alias (sin duplicados), usado fuera de la suscripción.
    function getInfosFromDatasources() {
        var infos = [];
        var seen = {};
        getDatasources().forEach(function(ds) {
            var info = getDeviceInfo(ds);
            if (info && !seen[info.id]) {
                seen[info.id] = true;
                infos.push(info);
            }
        });
        return infos;
    }

    function sortOrder() {
        order.sort(function(a, b) {
            return getDisplayName(devices[a]).localeCompare(getDisplayName(devices[b]), undefined, { numeric: true, sensitivity: 'base' });
        });
    }

    // Crea o actualiza un dispositivo con lo que hay en el servidor.
    // force = true pisa cambios locales. Devuelve true si hubo algo que redibujar.
    function upsertDevice(info, loadedModel, exists, force) {
        var device = devices[info.id];
        if (!device) {
            devices[info.id] = {
                id: info.id, entityType: info.entityType, name: info.name, exists: exists,
                model: loadedModel, remoteModel: cloneModel(loadedModel),
                dirty: false, pending: 0, loading: false, version: 0, lastSaveEnd: 0
            };
            order.push(info.id);
            return true;
        }

        // Siempre se recuerda lo último del servidor (sirve para Descartar).
        device.remoteModel = cloneModel(loadedModel);

        var changed = false;
        if (device.name !== info.name) { device.name = info.name; changed = true; }

        if (!force && (device.dirty || device.pending > 0)) { return changed; }

        device.exists = exists;
        if (JSON.stringify(device.model) !== JSON.stringify(loadedModel)) {
            device.model = loadedModel;
            changed = true;
        }
        if (force) { device.dirty = false; changed = true; }
        return changed;
    }

    // ======================================================
    // 7. LECTURA: SUSCRIPCIÓN EN TIEMPO REAL (con clave de datos)
    // ======================================================
    function onSubscriptionData(forceRender) {
        var controlKey = getControlKey();
        if (!controlKey || !ctx.data) { return; }

        var changed = !initialized || !!forceRender;
        var seen = {};

        ctx.data.forEach(function(entry) {
            if (!entry || !sameKey(entry.dataKey, controlKey)) { return; }
            var info = getDeviceInfo(entry.datasource);
            if (!info || seen[info.id]) { return; }
            seen[info.id] = true;

            var series = entry.data;
            var exists = !!(series && series.length);
            var raw = exists ? series[series.length - 1][1] : null;

            if (upsertDevice(info, buildLoadedModel(exists, raw), exists, false)) { changed = true; }
        });

        // Quita los dispositivos que ya no devuelve el alias (si no tienen cambios pendientes).
        order = order.filter(function(id) {
            var device = devices[id];
            if (seen[id] || device.dirty || device.pending > 0) { return true; }
            delete devices[id];
            changed = true;
            return false;
        });

        initialized = true;
        emptyText = 'El alias del widget no devuelve dispositivos.';
        if (changed) {
            sortOrder();
            renderTable();
            updateActions();
        }
    }

    // ======================================================
    // 8. ESCRITURA por servicio nativo; LECTURA via WebSocket
    // ======================================================
    function saveDevice(device, previousModel) {
        device.pending++;
        renderTable();

        ctx.attributeService.saveEntityAttributes(
            { entityType: device.entityType, id: device.id },
            attributeScope,
            [{ key: getAttributeName(), value: buildPayload(device) }]
        ).subscribe(
            function() {
                device.pending--;
                device.lastSaveEnd = Date.now();
                device.exists = true;
                if (device.pending === 0) {
                    device.dirty = false;
                    device.remoteModel = cloneModel(device.model);
                }
                renderTable();
                updateActions();
                notify('success', 'Guardado: ' + getDisplayName(device));
            },
            function(error) {
                device.pending--;
                device.lastSaveEnd = Date.now();
                if (previousModel) {
                    device.model = previousModel;   // revierte el cambio visual
                    device.dirty = device.pending > 0;
                }
                renderTable();
                updateActions();
                notify('error', 'Error al guardar "' + getDisplayName(device) + '"' + errorDetail(error) + '. Revisa los permisos.');
            }
        );
    }

    function saveAllDirty() {
        order.forEach(function(id) {
            var device = devices[id];
            if (device.dirty && device.pending === 0) { saveDevice(device, null); }
        });
    }

    // Vuelve cada dispositivo modificado a lo último que hay en el servidor.
    function discardChanges() {
        editing = null;
        order.forEach(function(id) {
            var device = devices[id];
            if (device.dirty && device.pending === 0) {
                device.model = cloneModel(device.remoteModel);
                device.dirty = false;
                device.version++;
            }
        });
        renderTable();
        updateActions();
    }

    // ======================================================
    // 9. CAMBIOS DEL USUARIO (con confirmación si cambia la estructura)
    // ======================================================
    function onDeviceChanged(device, previousModel) {
        device.version++;
        device.dirty = true;
        updateActions();
        if (autoSave) { saveDevice(device, previousModel); }
        else { renderTable(); }
    }

    function commitEdits(device, edits) {
        var previous = cloneModel(device.model);
        edits.forEach(function(edit) { setCellValue(device, edit.column, edit.value); });
        onDeviceChanged(device, previous);
    }

    // Mensajes de lo que alterará la estructura del JSON: campos nuevos o cambios de tipo.
    function describeChanges(device, edits) {
        var messages = [];
        var name = getDisplayName(device);

        if (!device.exists) {
            messages.push('El atributo "' + getAttributeName() + '" no existe en "' + name + '" y se creará.');
        }

        edits.forEach(function(edit) {
            var key = edit.column.key;
            if (key === SINGLE_KEY) {
                if (kindLabel(device.model.data) !== kindLabel(edit.value)) {
                    messages.push('El valor del atributo cambiará de tipo: de ' + kindLabel(device.model.data)
                        + ' a ' + kindLabel(edit.value) + '.');
                }
                return;
            }
            var current = device.model.data[key];
            if (current === undefined) {
                messages.push('Se creará el campo "' + key + '" (' + kindLabel(edit.value) + ') en "' + name + '".');
            } else if (kindLabel(current) !== kindLabel(edit.value)) {
                messages.push('El campo "' + key + '" de "' + name + '" cambiará de tipo de dato: de '
                    + kindLabel(current) + ' a ' + kindLabel(edit.value) + '.');
            }
        });
        return messages;
    }

    // Aplica los cambios; si crean campos o cambian tipos, pide confirmación antes.
    function requestChange(device, edits) {
        if (!edits.length) { return; }
        var messages = describeChanges(device, edits);
        if (!messages.length) {
            commitEdits(device, edits);
            return;
        }
        confirmAction(
            'Modificar la estructura del JSON',
            messages.join(' ') + ' ¿Deseas continuar?',
            function() { commitEdits(device, edits); },
            function() { renderTable(); }   // restaura lo que mostraba el control
        );
    }

    // ---- Edición de texto y número ----
    function isEditing(device, column) {
        return !!editing && editing.id === device.id && editing.key === column.key;
    }

    function startEditing(device, column, kind, currentValue) {
        editing = {
            id: device.id,
            key: column.key,
            kind: kind,
            draft: (currentValue === undefined || currentValue === null) ? '' : String(currentValue)
        };
        renderTable();
    }

    function cancelEditing() {
        editing = null;
        renderTable();
    }

    // Valida lo escrito en el editor (texto o número) y lo envía como cambio.
    function commitEditing(device, column) {
        if (!editing) { return; }
        var field = column.field;
        var value = editing.draft;

        if (editing.kind === 'number') {
            if (clean(value) === '' || isNaN(Number(value))) {
                notify('error', 'Ingresa un número válido.');
                return;
            }
            value = Number(value);
            if (field && field.min !== null && value < field.min) {
                notify('error', 'El valor mínimo es ' + field.min + '.');
                return;
            }
            if (field && field.max !== null && value > field.max) {
                notify('error', 'El valor máximo es ' + field.max + '.');
                return;
            }
            if (field && field.integer && !Number.isInteger(value)) {
                notify('error', 'Este campo solo admite números enteros.'); return;
            }
            if (field && field.step !== null && field.step > 0) {
                var base = field.min !== null ? field.min : 0;
                var steps = (value - base) / field.step;
                if (Math.abs(steps - Math.round(steps)) > 1e-7) {
                    notify('error', 'El valor debe respetar el incremento de ' + field.step + '.'); return;
                }
            }
        }

        if (editing.kind === 'string' && field) {
            if (field.trim) value = value.trim();
            if (field.required && !value.length) { notify('error', 'Este campo es obligatorio.'); return; }
            if (field.minLength !== null && value.length < field.minLength) { notify('error', 'Longitud mínima: ' + field.minLength); return; }
            if (field.maxLength !== null && value.length > field.maxLength) { notify('error', 'Longitud máxima: ' + field.maxLength); return; }
            if (field.pattern) {
                try {
                    if (!(new RegExp(field.pattern)).test(value)) { notify('error', 'El texto no cumple el patrón requerido.'); return; }
                } catch(e) { notify('error', 'El patrón regex configurado no es válido.'); return; }
            }
        }
        editing = null;
        requestChange(device, [{ column: column, value: value }]);
    }

    // ======================================================
    // 10. RENDER
    // ======================================================
    function showMessage(text) {
        var message = document.createElement('div');
        message.className = 'attr-table__empty';
        message.textContent = text;
        scrollEl.appendChild(message);
    }

    function createIcon(name) {
        var icon = document.createElement('mat-icon');
        icon.className = 'attr-table__icon mat-icon notranslate material-icons mat-ligature-font mat-icon-no-color';
        icon.setAttribute('role', 'img');
        icon.setAttribute('aria-hidden', 'true');
        icon.textContent = name;
        return icon;
    }

    function createTextButton(text, onClick) {
        var button = document.createElement('button');
        button.type = 'button';
        button.className = 'attr-table__link-btn';
        button.textContent = text;
        button.addEventListener('click', onClick);
        return button;
    }

    function createIconButton(iconName, title, onClick) {
        var button = document.createElement('button');
        button.type = 'button';
        button.className = 'attr-table__icon-btn';
        button.title = title;
        button.appendChild(createIcon(iconName));
        button.addEventListener('click', onClick);
        return button;
    }

    function appendUnit(parent, field) {
        if (field && field.unit) {
            var unit = document.createElement('span');
            unit.className = 'attr-table__unit';
            unit.textContent = field.unit;
            parent.appendChild(unit);
        }
    }

    // Casilla true/false
    function createBooleanControl(device, column, info) {
        var checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.className = 'attr-table__checkbox';
        checkbox.checked = !!info.value;
        checkbox.disabled = !!(column.field && column.field.readOnly) || device.pending > 0;
        checkbox.addEventListener('change', function() {
            requestChange(device, [{ column: column, value: checkbox.checked }]);
        });
        return checkbox;
    }

    // Lista desplegable con las opciones definidas en el widget
    function createSelectControl(device, column, info) {
        var field = column.field;
        var select = document.createElement('select');
        select.className = 'attr-table__select';
        select.disabled = !!field.readOnly || device.pending > 0;

        function addOption(value, label, isSelected, isDisabled) {
            var option = document.createElement('option');
            option.value = value;
            option.textContent = label;
            if (isSelected) { option.selected = true; }
            if (isDisabled) { option.disabled = true; }
            select.appendChild(option);
        }

        var hasValue = info.value !== undefined;
        var matched = false;
        if (!hasValue) { addOption('', '—', true, true); }

        field.options.forEach(function(option) {
            var isSelected = hasValue && String(option.value) === String(info.value);
            if (isSelected) { matched = true; }
            addOption(String(option.value), option.label, isSelected, false);
        });

        // Valor actual que no está en la lista: se muestra para no falsear el dato.
        if (hasValue && !matched) { addOption(String(info.value), String(info.value), true, false); }
        if (field.allowCustom) { addOption(CUSTOM_OPTION, 'Otro…', false, false); }

        select.addEventListener('change', function() {
            if (select.value === CUSTOM_OPTION) {
                startEditing(device, column, field.type, info.value);
                return;
            }
            var chosen = field.options.filter(function(option) { return String(option.value) === select.value; })[0];
            if (chosen) { requestChange(device, [{ column: column, value: chosen.value }]); }
        });
        return select;
    }

    // Editor de texto o número con íconos aceptar / cancelar
    function createEditor(device, column) {
        var field = column.field;
        var wrap = document.createElement('span');
        wrap.className = 'attr-table__editor';

        var input = document.createElement('input');
        input.className = 'attr-table__input';
        input.type = editing.kind === 'number' ? 'number' : 'text';
        if (editing.kind === 'number') {
            input.step = 'any';
            if (field && field.min !== null) { input.min = field.min; }
            if (field && field.max !== null) { input.max = field.max; }
        }
        if (field && editing.kind === 'number' && field.step !== null && field.step > 0) input.step = field.step;
        if (field && editing.kind === 'string') {
            if (field.maxLength !== null) input.maxLength = field.maxLength;
            if (field.minLength !== null) input.minLength = field.minLength;
        }
        input.value = editing.draft;
        input.addEventListener('input', function() { editing.draft = input.value; });
        input.addEventListener('keydown', function(event) {
            if (event.key === 'Enter') { commitEditing(device, column); }
            else if (event.key === 'Escape') { cancelEditing(); }
        });

        wrap.appendChild(input);
        wrap.appendChild(createIconButton('check', 'Aceptar', function() { commitEditing(device, column); }));
        wrap.appendChild(createIconButton('close', 'Cancelar', cancelEditing));
        return wrap;
    }

    // Valor de texto o número con ícono de editar a la derecha
    function createValueControl(device, column, info) {
        var wrap = document.createElement('span');

        var value = document.createElement('span');
        value.className = info.missing ? 'attr-table__value--empty' : 'attr-table__value';
        value.textContent = info.missing ? '—' : String(info.value);
        wrap.appendChild(value);
        if (!info.missing) { appendUnit(wrap, column.field); }

        if (!(column.field && column.field.readOnly) && device.pending === 0) {
            wrap.appendChild(createIconButton('edit', 'Editar', function() {
                startEditing(device, column, info.kind, info.value);
            }));
        }
        return wrap;
    }

    function createCell(device, column) {
        var cell = document.createElement('td');
        var info = getCellInfo(device, column);

        if (!info) {
            var missing = document.createElement('span');
            missing.className = 'attr-table__missing';
            missing.textContent = '–';
            cell.appendChild(missing);
        } else if (info.kind === 'boolean') {
            cell.appendChild(createBooleanControl(device, column, info));
        } else if (isEditing(device, column)) {
            cell.appendChild(createEditor(device, column));
        } else if (column.field && column.field.mode === 'options' && column.field.options.length) {
            cell.appendChild(createSelectControl(device, column, info));
        } else {
            cell.appendChild(createValueControl(device, column, info));
        }
        return cell;
    }

    // Botones Todos / Ninguno: afectan solo a los campos booleanos de la fila.
    function setBooleansInRow(device, value, columns) {
        var edits = [];
        columns.forEach(function(column) {
            var info = getCellInfo(device, column);
            if (info && info.kind === 'boolean' && !(column.field && column.field.readOnly) && (info.missing || info.value !== value)) {
                edits.push({ column: column, value: value });
            }
        });
        requestChange(device, edits);
    }

    // ---- Paginación ----
    function clampPage() {
        var pages = Math.max(1, Math.ceil(order.length / pageSize));
        if (pageIndex > pages - 1) { pageIndex = pages - 1; }
        if (pageIndex < 0) { pageIndex = 0; }
    }

    function getPageIds() {
        if (!paginationEnabled) { return order; }
        var start = pageIndex * pageSize;
        return order.slice(start, start + pageSize);
    }

    function goToPage(index) {
        editing = null;
        pageIndex = index;
        renderTable();
    }

    function renderPaginator() {
        paginatorEl.innerHTML = '';
        if (!paginationEnabled) {
            paginatorEl.style.display = 'none';
            return;
        }
        paginatorEl.style.display = 'flex';

        var total = order.length;
        var start = total ? pageIndex * pageSize + 1 : 0;
        var end = Math.min(total, (pageIndex + 1) * pageSize);

        var label = document.createElement('span');
        label.textContent = 'Dispositivos por página:';
        paginatorEl.appendChild(label);

        var sizes = [5, 10, 25, 50, 100];
        if (sizes.indexOf(pageSize) === -1) {
            sizes.push(pageSize);
            sizes.sort(function(a, b) { return a - b; });
        }
        var select = document.createElement('select');
        select.className = 'attr-table__select attr-table__pager-select';
        sizes.forEach(function(size) {
            var option = document.createElement('option');
            option.value = String(size);
            option.textContent = String(size);
            if (size === pageSize) { option.selected = true; }
            select.appendChild(option);
        });
        select.addEventListener('change', function() {
            editing = null;
            pageSize = Number(select.value);
            pageIndex = 0;
            renderTable();
        });
        paginatorEl.appendChild(select);

        var range = document.createElement('span');
        range.className = 'attr-table__pager-range';
        range.textContent = start + ' – ' + end + ' de ' + total;
        paginatorEl.appendChild(range);

        var previous = createIconButton('chevron_left', 'Página anterior', function() { goToPage(pageIndex - 1); });
        previous.disabled = pageIndex === 0;
        paginatorEl.appendChild(previous);

        var next = createIconButton('chevron_right', 'Página siguiente', function() { goToPage(pageIndex + 1); });
        next.disabled = end >= total;
        paginatorEl.appendChild(next);
    }

    function renderTable() {
        renderDetectedKeys();
        renderDiagnostics();
        scrollEl.innerHTML = '';
        clampPage();
        renderPaginator();

        if (!order.length) {
            showMessage(emptyText);
            return;
        }

        var columns = getColumns();
        if (!columns.length) {
            showMessage('Ningún dispositivo tiene campos simples en el atributo "' + getAttributeName()
                + '". Define los campos a mostrar en los ajustes del widget.');
            return;
        }

        var hasBooleans = showRowButtons && columns.some(isBooleanColumn);
        var infoKeys = getInfoKeys();

        var table = document.createElement('table');
        table.className = 'attr-table__table';

        // Encabezado
        var headRow = document.createElement('tr');
        function addHead(text) {
            var th = document.createElement('th');
            th.textContent = text;
            headRow.appendChild(th);
        }
        if (infoKeys.length) {
            infoKeys.forEach(function(key) { addHead(getKeyLabel(key)); });
        } else {
            addHead(getKeyLabel(getControlKey()));
        }
        columns.forEach(function(column) { addHead(column.label); });
        if (hasBooleans) { addHead('Acciones'); }

        var thead = document.createElement('thead');
        thead.appendChild(headRow);
        table.appendChild(thead);

        // Filas: una por dispositivo
        var tbody = document.createElement('tbody');
        getPageIds().forEach(function(id) {
            var device = devices[id];
            var row = document.createElement('tr');
            row.className = 'attr-table__row'
                + (device.dirty ? ' attr-table__row--dirty' : '')
                + (device.pending > 0 ? ' attr-table__row--saving' : '');

            if (infoKeys.length) {
                infoKeys.forEach(function(key) {
                    var infoCell = document.createElement('td');
                    infoCell.textContent = (valuesById[device.id] || {})[keyId(key)] || device.name;
                    row.appendChild(infoCell);
                });
            } else {
                var nameCell = document.createElement('td');
                nameCell.textContent = device.name;
                row.appendChild(nameCell);
            }

            columns.forEach(function(column) { row.appendChild(createCell(device, column)); });

            if (hasBooleans) {
                var actions = document.createElement('td');
                actions.appendChild(createTextButton('Todos', function() { setBooleansInRow(device, true, columns); }));
                actions.appendChild(createTextButton('Ninguno', function() { setBooleansInRow(device, false, columns); }));
                row.appendChild(actions);
            }
            tbody.appendChild(row);
        });
        table.appendChild(tbody);
        scrollEl.appendChild(table);

        // Si hay una celda en edición, el cursor vuelve al campo tras redibujar.
        if (editing) {
            var input = scrollEl.querySelector('.attr-table__input');
            if (input) {
                input.focus();
                try { input.setSelectionRange(input.value.length, input.value.length); } catch (e) { /* number no admite selección */ }
            }
        }
    }

    // ======================================================
    // DIAGNÓSTICO: verifica cada origen por separado
    // ======================================================
    var KEY_TYPE_LABELS = { entityField: 'campo de entidad', attribute: 'atributo', timeseries: 'telemetría', function: 'función', count: 'conteo' };

    function diagnose() {
        var items = [];
        function add(level, text) { items.push({ level: level, text: text }); }
        var keys = resolveKeys();
        var typeOf = function(key) { return KEY_TYPE_LABELS[key.type] || key.type; };

        // -- Columna de datos
        if (keys.data) {
            add('ok', 'Columna de datos: clave "' + keys.data.name + '" (' + typeOf(keys.data) + '). Encabezado: "'
                + getKeyLabel(keys.data) + '".');
        } else {
            add('warn', 'Columna de datos: no hay clave configurada; la primera columna mostrará el nombre de la entidad.');
        }

        // -- Atributo JSON
        if (keys.json) {
            add('ok', 'Atributo JSON: clave "' + keys.json.name + '" (se guarda en ' + attributeScope + ').');
        } else if (keys.badType) {
            add('error', 'Atributo JSON: la clave "' + keys.badType.name + '" es de tipo ' + typeOf(keys.badType)
                + '; debe ser de tipo Atributo.');
        } else {
            add('error', 'Atributo JSON: falta una clave de tipo Atributo con el JSON editable (2.º origen o función ATRIBUTO JSON).');
        }
        if (keys.data && keys.json && sameKey(keys.data, keys.json)) {
            add('error', 'La columna de datos y el atributo JSON usan la misma clave ("' + keys.json.name + '").');
        }

        // -- Contenido recibido por la suscripción
        var dataIds = {}, jsonIds = {}, keyNames = {};
        var st = { object: 0, missing: 0, scalar: 0, invalid: 0, array: 0, noName: 0 };
        (ctx.data || []).forEach(function(entry) {
            if (!entry || !entry.dataKey) { return; }
            var info = getDeviceInfo(entry.datasource);
            if (!info) { return; }
            var series = entry.data;
            var exists = !!(series && series.length);
            var raw = exists ? series[series.length - 1][1] : null;

            if (keys.data && sameKey(entry.dataKey, keys.data) && dataIds[info.id] === undefined) {
                dataIds[info.id] = clean(formatValue(raw)) !== '';
                if (!dataIds[info.id]) { st.noName++; }
            }
            if (keys.json && sameKey(entry.dataKey, keys.json) && jsonIds[info.id] === undefined) {
                jsonIds[info.id] = true;
                if (!exists || raw === null || raw === undefined || raw === '') { st.missing++; return; }
                var value = raw, parsed = true;
                if (typeof value === 'string') { try { value = JSON.parse(value); } catch (e) { parsed = false; } }
                if (!parsed) { st.invalid++; }
                else if (Array.isArray(value)) { st.array++; }
                else if (value !== null && typeof value === 'object') {
                    st.object++;
                    Object.keys(value).forEach(function(k) { keyNames[k] = true; });
                } else { st.scalar++; }
            }
        });

        var ids = {};
        Object.keys(dataIds).concat(Object.keys(jsonIds)).forEach(function(id) { ids[id] = true; });
        var total = Object.keys(ids).length;

        if (keys.json) {
            if (!total) {
                add('warn', initialized ? 'El alias no devuelve dispositivos.' : 'Esperando datos de la suscripción…');
            } else {
                add('ok', 'Dispositivos recibidos: ' + total + '.');
                var onlyData = Object.keys(dataIds).filter(function(id) { return jsonIds[id] === undefined; }).length;
                var onlyJson = Object.keys(jsonIds).filter(function(id) { return dataIds[id] === undefined; }).length;
                if (keys.data && Object.keys(dataIds).length && (onlyData || onlyJson)) {
                    add('warn', 'Los dos orígenes no apuntan a las mismas entidades (' + onlyData + ' solo en la columna de datos, '
                        + onlyJson + ' solo en el atributo JSON). Usa el mismo alias en ambos.');
                }
                if (keys.data && st.noName) {
                    add('warn', st.noName + ' dispositivo(s) sin valor en la clave "' + keys.data.name + '": se muestra el nombre de la entidad.');
                }
                if (st.object) { add('ok', 'JSON válido (objeto) en ' + st.object + ' de ' + Object.keys(jsonIds).length + ' dispositivo(s).'); }
                if (st.missing) { add('warn', st.missing + ' dispositivo(s) sin el atributo "' + keys.json.name + '" (se creará al editar).'); }
                if (st.scalar) { add('warn', st.scalar + ' dispositivo(s) con un valor simple en lugar de un objeto JSON.'); }
                if (st.invalid) { add('warn', st.invalid + ' dispositivo(s) con texto que no es JSON válido.'); }
                if (st.array) { add('warn', st.array + ' dispositivo(s) con una lista (array); no se muestra como columnas.'); }
                if (declaredFields.length && st.object) {
                    var absent = declaredFields.filter(function(f) { return !keyNames[f.key]; }).map(function(f) { return f.key; });
                    if (absent.length) {
                        add('warn', 'Campos configurados que no existen en ningún JSON (revisa mayúsculas/ortografía): ' + absent.join(', ') + '.');
                    } else {
                        add('ok', 'Los ' + declaredFields.length + ' campo(s) configurados existen en el JSON.');
                    }
                } else if (!declaredFields.length && st.object) {
                    add('ok', 'Modo automático: ' + Object.keys(keyNames).length + ' campo(s) detectados en el JSON.');
                }
            }
        }
        return items;
    }

    function renderDiagnostics() {
        var items = diagnose();
        var worst = items.some(function(i) { return i.level === 'error'; }) ? 'error'
            : (items.some(function(i) { return i.level === 'warn'; }) ? 'warn' : 'ok');
        diagDot.className = 'attr-table__diag-dot attr-table__diag-dot--' + worst;
        diagPanel.replaceChildren();
        diagPanel.style.display = diagShown ? 'flex' : 'none';
        diagToggle.setAttribute('data-status', worst);
        if (!diagShown) { return items; }
        var iconByLevel = { ok: 'check_circle', warn: 'warning', error: 'error' };
        items.forEach(function(item) {
            var line = document.createElement('div');
            line.className = 'attr-table__diag-item attr-table__diag-item--' + item.level;
            line.appendChild(createIcon(iconByLevel[item.level]));
            var text = document.createElement('span');
            text.textContent = item.text;
            line.appendChild(text);
            diagPanel.appendChild(line);
        });
        return items;
    }

    saveBtn.addEventListener('click', saveAllDirty);
    discardBtn.addEventListener('click', discardChanges);

    // ======================================================
    // 11. INICIO: solo datos de la suscripción de ThingsBoard
    // ======================================================
    self.attrTable = {
        onData: function() {
            var infoChanged = updateInfoValues();
            if (getControlKey()) {
                onSubscriptionData(infoChanged);
            } else {
                var problems = diagnose().filter(function(item) { return item.level === 'error'; });
                setEmptyText(problems.length ? problems[0].text
                    : 'Configura la columna de datos (nombre) y el atributo JSON (tipo Atributo).');
            }
            renderDiagnostics();
        },
        destroy: function() {}
    };

    renderTable();
    updateActions();

    self.attrTable.onData();
};

self.onResize = function() {};

self.onDataUpdated = function() {
    if (self.attrTable) { self.attrTable.onData(); }
};

self.typeParameters = function() {
    return {
        maxDatasources: 2,
        minDatasources: 1,
        dataKeysOptional: false
    };
};

self.onDestroy = function() {
    if (self.attrTable) { self.attrTable.destroy(); }
};
